import{_ as o,o as i,c as d,a2 as r}from"./chunks/framework.BWuWLRhz.js";const P=JSON.parse('{"title":"예제 플러그인","description":"","frontmatter":{},"headers":[],"relativePath":"ko-KR/dev-guide/examples.md","filePath":"ko-KR/dev-guide/examples.md","lastUpdated":1785993908000}'),c={name:"ko-KR/dev-guide/examples.md"};function t(a,e,n,s,l,g){return i(),d("div",null,[...e[0]||(e[0]=[r('<h1 id="예제-플러그인" tabindex="-1">예제 플러그인 <a class="header-anchor" href="#예제-플러그인" aria-label="Permalink to &quot;예제 플러그인&quot;">​</a></h1><p>Lertaro 자체에는 두 개의 플러그인이 함께 제공되며, 둘 다 실전에서 유용한 참고 예제입니다 — 두 플러그인 모두 Lertaro 저장소의 <code>Plugins/</code> 폴더에 있습니다.</p><h2 id="coreextensions-—-동작과-셸-컨텍스트-메뉴" tabindex="-1">CoreExtensions — 동작과 셸 컨텍스트 메뉴 <a class="header-anchor" href="#coreextensions-—-동작과-셸-컨텍스트-메뉴" aria-label="Permalink to &quot;CoreExtensions — 동작과 셸 컨텍스트 메뉴&quot;">​</a></h2><p><code>CoreExtensionsPlugin</code>은 <code>IPlugin</code>, <code>IActionProvider</code>, <code>IConfigurable</code> 세 가지 인터페이스를 동시에 구현합니다.</p><ul><li><strong><code>IActionProvider.GetActions()</code></strong> 는 열 개의 내장 <code>ISearchResultAction</code>을 반환합니다 — 열기, 탐색기에서 위치 찾기, 경로 복사, 파일 자체를 복사/잘라내기, 해당 위치에서 명령 프롬프트 열기, 파일/폴더 생성, 그리고 열기와 명령 프롬프트의 상승된(관리자 권한 실행) 변형까지 포함합니다.</li><li><strong><code>IActionProvider.GetDynamicActionProviders()</code></strong> 는 단 하나의 <code>IDynamicActionProvider</code> — <code>ShellMenuActionProvider</code> — 를 반환합니다. 이것이 바로 실제 Windows 마우스 우클릭 메뉴(중첩된 계단식 하위 메뉴, 예를 들어 &quot;보내기&quot;까지 포함)가 Lertaro 자체의 Actions 메뉴 안에 나타나게 만드는 방식입니다. 고정된 동작 목록이 아니라 <em>어떤</em> 외부의, 동적으로 구성되는 메뉴든 Lertaro 안에 그대로 노출하고 싶다면 이 패턴을 그대로 참고하면 됩니다.</li><li><strong><code>IConfigurable.GetConfigSchema()</code></strong> 는 중첩된 필드 그룹과 <code>StringList</code> 필드 타입을 사용하는 설정 스키마를 보여줍니다 — 여러분의 플러그인이 설정 → 플러그인 구성 대화상자에서 단순한 불리언 목록 이상을 필요로 한다면 읽어볼 가치가 있습니다.</li><li>다섯 개의 프로바이더가 <a href="./sdk/ui-extensions.html#iquickpaneltabprovider"><code>IQuickPanelTabProvider</code></a>를 구현하며, 이들이 합쳐 이 인터페이스의 양 극단을 보여줍니다. <code>FavoritesTabProvider</code>와 <code>HistoryTabProvider</code>는 메모리에 있는 목록을 그대로 돌려줍니다 — 둘 다 자체 상태가 없으므로 최소한의 참고 예제입니다. <code>WindowsRecentTabProvider</code>가 반대쪽 극단으로, 백그라운드 작업에서 디렉터리를 읽고 COM으로 셸 바로 가기를 해석하되 비싼 작업 <strong>전에</strong> 개수를 먼저 잘라내며, 각 항목의 <code>Metadata.Modified</code>를 채워 탭의 최신순 정렬이 의미를 갖게 합니다.</li><li><code>LastDirectoryTabProvider</code>와 <code>RecentFilesTabProvider</code>는 읽어 볼 이유가 조금 다릅니다: 둘 다 자기 데이터가 아예 없고, <a href="./sdk/services.html"><code>ExplorerPathService</code></a>와 <code>RecentFilesService</code>를 통해 호스트에 물어봅니다. 플러그인으로 보여 주고 싶은 것을 Lertaro가 이미 알고 있다면 이 패턴을 따라 하세요.</li></ul><h2 id="pinyinalias-—-중국어-파일명을-위한-병음-별칭" tabindex="-1">PinyinAlias — 중국어 파일명을 위한 병음 별칭 <a class="header-anchor" href="#pinyinalias-—-중국어-파일명을-위한-병음-별칭" aria-label="Permalink to &quot;PinyinAlias — 중국어 파일명을 위한 병음 별칭&quot;">​</a></h2><p><code>PinyinAliasProvider</code>는 <code>IAliasProvider</code>와 <code>ITranslationProvider</code>를 모두 구현합니다 — 관련이 있는 SDK 역할이라면 플러그인이 자유롭게 결합할 수 있으며, 이 플러그인이 그 좋은 예시입니다.</p><ul><li><strong><code>IAliasProvider.InputRanges</code>/<code>OutputRanges</code></strong> 는 매직 넘버를 중복해서 적는 대신 <code>PinyinEngine</code> 자체의 테이블 범위로부터 두 알파벳을 그대로 선언합니다(<code>InputRanges</code>: CJK 블록, <code>OutputRanges</code>: <code>a</code>-<code>z</code>) — 호스트는 이 둘을 함께 사용하여 <code>大长今</code>을 대상으로 한 <code>大cj</code>처럼 리터럴과 병음이 혼합된 쿼리 항목을 지원합니다.</li><li><strong><code>IAliasProvider.CanHandle(text)</code></strong> 는 실제 작업을 수행하기 전에 중국어 문자가 있는지 먼저 스캔하므로, 중국어가 아닌 파일명은 별칭 생성을 완전히 건너뜁니다.</li><li><strong><code>IAliasProvider.GetAliases(text)</code></strong> 는 문자별 음절 테이블(각 중국어 문자를 가능한 병음 발음에 매핑)을 구축한 뒤, 전체 병음 별칭과 이니셜만으로 된 별칭을 함께 생성합니다. 다음자(하나 이상의 유효한 발음을 가진 문자)가 포함된 파일명의 경우, 흔히 쓰이는 모든 조합에 대해 별칭을 생성합니다 — 병적인 입력에서 조합 폭발이 일어나지 않도록 32개 조합으로 상한을 두며, 각 대안을 <code>|</code>로 이어붙여 검색 엔진이 모든 대안이 동시에 일치해야 하는 것이 아니라 각각을 하나의 후보로 취급하도록 합니다.</li><li><strong><code>ITranslationProvider</code></strong> 는 <em>같은</em> 클래스에 구현되어 있으며, 이는 순전히 이 플러그인 자체의 UI 문자열 (예: 표시 이름)을 <code>TranslationService.LoadEmbeddedTranslations</code>를 통해 제공하기 위한 것입니다 — 두 인터페이스는 목적상 서로 무관하지만, 작고 단일 파일로 이루어진 플러그인이다 보니 우연히 한 타입에 함께 놓여 있을 뿐입니다.</li><li><code>lock</code>으로 보호되는 <code>Dictionary&lt;string, Dictionary&lt;string, string&gt;&gt;</code> 캐시는 호출할 때마다 내장된 번역 JSON을 다시 파싱하지 않도록 해줍니다 — <code>GetTranslations</code>에서 사소하지 않은 작업을 수행하는 모든 플러그인에 적용되는 표준 패턴입니다.</li></ul><p>두 플러그인을 나란히 읽어보는 것이 <a href="./sdk/core-search-actions.html">Plugin SDK 참조</a>의 각 구성 요소가 실제로 어떻게 맞물리는지 가장 빠르게 파악하는 방법입니다.</p>',9)])])}const p=o(c,[["render",t]]);export{P as __pageData,p as default};
